#include "test_framework.h"
#include "WebSettings.h"
#include "StorageManager.cpp"
#include <cstring>
static void clearStore(){s_hostUints.clear();s_hostStrings.clear();s_hostBlobs.clear();s_hostCsvFile.clear();s_hostFailWrites=false;s_hostFailBlobKey.clear();s_hostFailAfterWrites=-1;s_hostSuccessfulWrites=0;}
TEST_TIER1(M2_DefaultNamesSurviveNewEnvelope){clearStore();StorageManager s;MaintenanceEngine m;ASSERT_TRUE(s.saveItems(m.getItems()));std::vector<MaintenanceItem>a;ASSERT_TRUE(s.loadItems(a));for(size_t i=0;i<a.size();i++)ASSERT_EQ(a[i].name,m.getItems()[i].name);}
TEST_TIER2(M2_Utf8BoundaryRamAndReloadMatch){clearStore();MaintenanceEngine m;std::string name;for(int i=0;i<40;i++)name+="ก";ASSERT_TRUE(m.addItem(name,1000,0,98540,""));StorageManager s;ASSERT_TRUE(s.saveItems(m.getItems()));std::vector<MaintenanceItem>a;ASSERT_TRUE(s.loadItems(a));ASSERT_EQ(a.back().name,m.getItems().back().name);ASSERT_EQ(a.back().name.size(),77u);std::string clean;ASSERT_TRUE(StorageManager::normalizeUtf8(a.back().name,79,clean));}
TEST_TIER2(M2_ControlsAndInvalidUtf8Rejected){std::string clean;ASSERT_FALSE(StorageManager::normalizeUtf8("A\nB",79,clean));ASSERT_FALSE(StorageManager::normalizeUtf8(std::string("A\0B",3),79,clean));ASSERT_FALSE(StorageManager::normalizeUtf8(std::string("\xE0\xB8",2),79,clean));ASSERT_FALSE(StorageManager::normalizeUtf8(std::string("\xED\xA0\x80",3),79,clean));}
TEST_TIER1(M2_Legacy100MigrationPreservesConfiguration){clearStore();LegacyItem old{};std::strcpy(old.id,"custom_15");std::strcpy(old.name,"custom service");std::strcpy(old.lastDate,"unknown");old.intervalKm=12345;old.intervalDays=123;old.warnPct=17;old.lastKm=99887;old.lastEpoch=22;old.flags=2;s_hostUints["item_count"]=1;auto bytes=reinterpret_cast<uint8_t*>(&old);s_hostBlobs["items_blob"]={bytes,bytes+sizeof(old)};StorageManager s;std::vector<MaintenanceItem>a;ASSERT_TRUE(s.loadItems(a));ASSERT_EQ(a[0].intervalKm,12345u);ASSERT_EQ(a[0].lastKm,99887u);ASSERT_EQ(a[0].name,"custom service");ASSERT_FALSE(a[0].visible);ASSERT_TRUE(s_hostBlobs.count("items_v2")!=0);ASSERT_TRUE(s_hostBlobs.count("items_blob")!=0);}
TEST_TIER2(M2_LegacyTruncatedThaiRecoversCompletePrefix){clearStore();LegacyItem old{};std::strcpy(old.id,"oil");old.intervalKm=12345;old.warnPct=10;old.flags=1;std::string longName;for(int i=0;i<20;i++)longName+="ก";std::memcpy(old.name,longName.data(),47);s_hostUints["item_count"]=1;auto bytes=reinterpret_cast<uint8_t*>(&old);s_hostBlobs["items_blob"]={bytes,bytes+sizeof(old)};StorageManager s;std::vector<MaintenanceItem>a;ASSERT_TRUE(s.loadItems(a));ASSERT_EQ(a[0].name.size(),45u);ASSERT_EQ(a[0].intervalKm,12345u);}
TEST_TIER2(M2_ChecksumFailurePreservesCallerAndSavedBytes){clearStore();StorageManager s;MaintenanceEngine m;ASSERT_TRUE(s.saveItems(m.getItems()));s_hostBlobs["items_v2"].back()^=1;auto before=s_hostBlobs["items_v2"];auto a=m.getItems();ASSERT_FALSE(s.loadItems(a));ASSERT_EQ(a.size(),14u);ASSERT_TRUE(before==s_hostBlobs["items_v2"]);ASSERT_TRUE(s.hasItemsData());}
TEST_TIER2(M2_MigrationWriteFailureKeepsLegacy){clearStore();LegacyItem old{};std::strcpy(old.id,"oil");std::strcpy(old.name,"oil");old.warnPct=10;s_hostUints["item_count"]=1;auto bytes=reinterpret_cast<uint8_t*>(&old);s_hostBlobs["items_blob"]={bytes,bytes+sizeof(old)};auto before=s_hostBlobs["items_blob"];s_hostFailWrites=true;StorageManager s;std::vector<MaintenanceItem>a;ASSERT_FALSE(s.loadItems(a));ASSERT_TRUE(a.empty());ASSERT_TRUE(before==s_hostBlobs["items_blob"]);}
TEST_TIER1(M2_MatchedMileagePidAndFractionCheckpoint){clearStore();StorageManager s;ASSERT_TRUE(s.saveOdometerCheckpoint(100123,1234,true,0.75f));StorageManager fresh;uint32_t odo=0,pid=0;bool valid=false;float fraction=0;ASSERT_TRUE(fresh.loadOdometerCheckpoint(odo,pid,valid,&fraction));ASSERT_EQ(odo,100123u);ASSERT_EQ(pid,1234u);ASSERT_TRUE(valid);ASSERT_NEAR(fraction,0.75f,0.001f);s_hostFailWrites=true;ASSERT_FALSE(s.saveOdometerCheckpoint(999999,4321,true));ASSERT_TRUE(fresh.loadOdometerCheckpoint(odo,pid,valid));ASSERT_EQ(odo,100123u);ASSERT_EQ(pid,1234u);}
TEST_TIER2(M2_LegacyIndependentPidNotTrusted){clearStore();s_hostUints["odo"]=123456;s_hostUints["last_pid31"]=100;StorageManager s;uint32_t odo,pid;bool valid;ASSERT_TRUE(s.loadOdometerCheckpoint(odo,pid,valid));ASSERT_EQ(odo,123456u);ASSERT_FALSE(valid);}
TEST_TIER3(M2_AlreadyDecodedHttpValuesPreserved){clearStore();StorageManager s;MaintenanceEngine m;OdometerEngine o;ObdTask b;bool dirty=false;std::map<std::string,std::string>p{{"new_name","A&B+C%20=D"},{"new_km","1000"}};ASSERT_EQ(WebSettings::handleDecodedParams(p,o,m,s,b,dirty),303);ASSERT_EQ(m.getItems().back().name,"🔧 A&B+C%20=D");for(auto&it:m.getItems())ASSERT_TRUE(it.visible);}
TEST_TIER2(M2_NegativeAndPrefixNumbersLeaveStateUntouched){clearStore();StorageManager s;MaintenanceEngine m;OdometerEngine o;ObdTask b;bool dirty=false;for(auto value:{"-1","100abc","4294967295"}){ASSERT_EQ(WebSettings::handleSavePayload(std::string("km_oil=")+value,o,m,s,b,dirty),400);ASSERT_EQ(m.getItems()[0].intervalKm,10000u);ASSERT_FALSE(dirty);}}
TEST_TIER2(M2_WriteFailureNotPublishedToScreen){clearStore();StorageManager s;MaintenanceEngine m;OdometerEngine o;ObdTask b;bool dirty=false;s_hostFailWrites=true;ASSERT_EQ(WebSettings::handleSavePayload("km_oil=22222",o,m,s,b,dirty),503);ASSERT_EQ(m.getItems()[0].intervalKm,10000u);ASSERT_FALSE(dirty);}
TEST_TIER2(M2_HtmlEscapesTextAndAttributes){MaintenanceEngine m;m.getItems()[0].name="<script>alert(1)</script>";auto html=WebSettings::renderHtmlPage(0,"x' onfocus='alert(1)","1234",m.getItems(),{});ASSERT_TRUE(html.find("<script>")==std::string::npos);ASSERT_TRUE(html.find("&lt;script&gt;")!=std::string::npos);ASSERT_TRUE(html.find("x&#39; onfocus=&#39;alert(1)")!=std::string::npos);}
TEST_TIER2(M2_CsvQuotesRoundtripAndControlsRejected){clearStore();StorageManager s;ServiceHistoryRecord r{"oil, \"special\"","",1,0,1,2};ASSERT_TRUE(s.appendHistoryLog(r));auto a=s.loadHistoryLogs();ASSERT_EQ(a.size(),1u);ASSERT_EQ(a[0].itemName,r.itemName);r.itemName="bad\nname";ASSERT_FALSE(s.appendHistoryLog(r));ASSERT_EQ(s.loadHistoryLogs().size(),1u);}
TEST_TIER3(M2_CustomIdsUniqueAfterRemoval){MaintenanceEngine m;ASSERT_TRUE(m.addItem("A",1000,0,0,""));auto first=m.getItems().back().id;ASSERT_TRUE(m.addItem("B",1000,0,0,""));auto second=m.getItems().back().id;ASSERT_TRUE(m.removeItem(first));ASSERT_TRUE(m.addItem("C",1000,0,0,""));ASSERT_NE(m.getItems().back().id,second);}
TEST_TIER3(M2_CalibrationClearsFractionInRamAndCheckpoint){clearStore();StorageManager s;MaintenanceEngine m;OdometerEngine o;ObdTask b;bool dirty=false;o.calibrate(98540);o.updateFromSpeed(36.0f,50.0f);ASSERT_NEAR(o.snapshot().fractionalKm,0.5f,0.001f);ASSERT_EQ(WebSettings::handleSavePayload("odo=100000",o,m,s,b,dirty),303);uint32_t odo,pid;bool valid;float fraction=1;ASSERT_TRUE(s.loadOdometerCheckpoint(odo,pid,valid,&fraction));ASSERT_EQ(odo,100000u);ASSERT_NEAR(fraction,0.0f,0.001f);ASSERT_NEAR(o.snapshot().fractionalKm,0.0f,0.001f);}
TEST_TIER3(M2_LaterBtFailureRollsBackItems){clearStore();StorageManager s;MaintenanceEngine m;OdometerEngine o;ObdTask b;bool dirty=false;ASSERT_TRUE(s.saveItems(m.getItems()));s_hostFailBlobKey="bt_v2";ASSERT_EQ(WebSettings::handleSavePayload("km_oil=15000&bt_name=Changed",o,m,s,b,dirty),503);std::vector<MaintenanceItem>durable;ASSERT_TRUE(s.loadItems(durable));ASSERT_EQ(durable[0].intervalKm,10000u);ASSERT_EQ(m.getItems()[0].intervalKm,10000u);ASSERT_FALSE(dirty);}
TEST_TIER3(M2_LaterOdoFailureRollsBackBtAndItems){clearStore();StorageManager s;MaintenanceEngine m;OdometerEngine o;ObdTask b;bool dirty=false;o.calibrate(98540);ASSERT_TRUE(s.saveItems(m.getItems()));ASSERT_TRUE(s.saveBtConfig("OBDII","1234"));ASSERT_TRUE(s.saveOdometerCheckpoint(98540,100,true));s_hostFailBlobKey="odo_v2";ASSERT_EQ(WebSettings::handleSavePayload("km_oil=15000&bt_name=Changed&odo=100000",o,m,s,b,dirty),503);std::vector<MaintenanceItem>durable;ASSERT_TRUE(s.loadItems(durable));ASSERT_EQ(durable[0].intervalKm,10000u);std::string name,pin;ASSERT_TRUE(s.loadBtConfig(name,pin));ASSERT_EQ(name,"OBDII");ASSERT_EQ(m.getItems()[0].intervalKm,10000u);ASSERT_EQ(o.getCurrentOdo(),98540u);ASSERT_FALSE(dirty);}
TEST_TIER3(M2_RollbackFailureReconcilesScreenWithDurableItems){clearStore();StorageManager s;MaintenanceEngine m;OdometerEngine o;ObdTask b;bool dirty=false;ASSERT_TRUE(s.saveItems(m.getItems()));s_hostSuccessfulWrites=0;s_hostFailAfterWrites=1;ASSERT_EQ(WebSettings::handleSavePayload("km_oil=15000&bt_name=Changed",o,m,s,b,dirty),503);std::vector<MaintenanceItem>durable;ASSERT_TRUE(s.loadItems(durable));ASSERT_EQ(durable[0].intervalKm,15000u);ASSERT_EQ(m.getItems()[0].intervalKm,durable[0].intervalKm);ASSERT_TRUE(dirty);}
TEST_TIER3(M2_StreamingPortalExactlyMatchesExistingHtml){MaintenanceEngine m;std::vector<ServiceHistoryRecord>history{{"oil, <special>","",100000,90000,10000,110000}};auto expected=WebSettings::renderHtmlPage(98540,"OBDII","1234",m.getItems(),history);std::string actual;size_t largest=0,chunks=0;WebSettings::ChunkedHtmlBuffer buffer([&](const char*p,size_t n){actual.append(p,n);largest=std::max(largest,n);++chunks;});std::ostream out(&buffer);WebSettings::renderHtmlTo(out,98540,"OBDII","1234",m.getItems(),history);out.flush();ASSERT_EQ(actual,expected);ASSERT_LE(largest,256u);ASSERT_GT(chunks,1u);std::cout<<"      [portal "<<actual.size()<<" bytes, maximum chunk "<<largest<<" bytes, "<<chunks<<" chunks]\n";}
int main(){return TestHarness::TestRunner::instance().runAll("M2 production regressions");}
